#include <stdint.h>

#include "clock_init.h"
#include "bsp_gpio.h"
#include "bsp_systick.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif


int main(void)
{
	// 將系統時脈切到 72 MHz
	// 對 GPIO 的影響： 本課的 GPIO 不依賴 72 MHz，用 8 MHz 也能動。
	// 放在最前面，是因為「開機先把時脈定好」是所有專案的慣例。
	uint32_t clock_state;
	clock_state = Clock_Init();
	while (clock_state != CLOCK_OK)
	{
		/**/
	}

	// 根據時鐘圖，FCLK 輸出跟 SYSCLK 有關係，所以要先設定好 SYSCLK
	// LOAD 是用 72 MHz 算出來的，所以要放在切到 72 MHz 的 Clock_Init() 之後
	BSP_SysTick_Init();

	// 進行 GPIO 初始化
	// 1. 啟動 GPIOB & GPIOC 時脈
	// 2. 設定 PC13 功能
	// 3. 設定 PB0 功能
	BSP_GPIO_Init();

	uint32_t start = BSP_SysTick_GetTick();
	uint32_t background_counter = 0U;
	for(;;)
	{
		// 亮 -> 延遲 500ms -> 暗 -> 延遲 500ms -> .....
		uint32_t now = BSP_SysTick_GetTick();
		if (now - start >= 500U)
		{
			BSP_GPIO_Led_Toggle();
			start = now;
		}
		background_counter ++;
	}
}
